arguments.new_str:
var builder = WebApplication.CreateBuilder(args);

// Breaking change #4: ValidateOnBuild/ValidateScopes now enabled in dev by default.
// A scoped service (IUserService) captured by a singleton (CacheService) violates scoping.
// Fix: register CacheService as scoped, or use IServiceScopeFactory inside the singleton.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService, CacheService>();

// Breaking change #1: HttpClientFactory now uses SocketsHttpHandler as the default primary
// handler. Casting to HttpClientHandler throws InvalidCastException.
// Fix: use ConfigurePrimaryHttpMessageHandler with an explicit handler.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Breaking change #3: HttpClientFactory Trace-level logs now redact all header values.
// Fix: explicitly allowlist non-sensitive headers you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(header =>
        header != "X-Request-Id" &&
        header != "X-Correlation-Id" &&
        header != "X-Forwarded-For" &&
        header != "X-Forwarded-Proto"));

// Breaking change #2: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers from
// proxies not in KnownProxies or KnownNetworks.
// Fix: add your reverse proxy addresses to KnownProxies/KnownNetworks.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto;
    // TODO: Replace with your actual reverse proxy IP address(es)
    options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

